CREATE OR REPLACE FUNCTION Stor_TBU_SMat_fn() RETURNS TRIGGER AS $$
Declare
  enableNegative NUMERIC := 0;
Begin
  Begin
    SELECT COALESCE(Value1,0)
      INTO enableNegative
      FROM Cpy_Pref
    WHERE UPPER(Key)=UPPER('Stor.Enable_SMAT_Negative');
  Exception
    When Others Then
      enableNegative := 0;
  End;
  If (enableNegative=1 AND COALESCE(NEW.CQnt,0)<0 And COALESCE(NEW.CQnt,0)<COALESCE(OLD.CQnt,0)) Then
    RAISE EXCEPTION '%', 'No Qnt. In Store '||NEW.Stor_Id||' For The Item '||NEW.Item_Id;
  End If;
  If (enableNegative=1 AND COALESCE(NEW.CQnt,0)=0 And COALESCE(NEW.CAmt,0)<>0) Then
    RAISE EXCEPTION '%', 'Item '||NEW.Item_Id||' on The Store '||NEW.Stor_Id||' Has Amount Without Quantity';
  End If;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

