CREATE OR REPLACE FUNCTION Stor_TBI_InTrn_fn() RETURNS TRIGGER AS $$
Declare
  nStr     NUMERIC;
  nBRate   NUMERIC := 0;
  nIcsId   NUMERIC;
  nSIcsId  NUMERIC;
  bPrices  Boolean := true;
  nCPrice  NUMERIC := 0;
  nNPrice  NUMERIC := 0;
  nDPrice  NUMERIC := 0;
  nSPrice  NUMERIC := 0;
  nWPrice  NUMERIC := 0;
  nRPrice  NUMERIC := 0;
  nHPrice  NUMERIC := 0;
  nMPrice  NUMERIC := 0;
Begin
  Select Stor_Id, Decode(Sign(COALESCE(BCurn_Rate,1)), -1,1, 0,1, COALESCE(BCurn_Rate,1))
    Into nStr   , nBRate
    From Stor_InMst
    Where Id=NEW.Mst_Id;
  NEW.Cst  := COALESCE(NEW.Amt,0);
  NEW.BAmt := Round(COALESCE(NEW.Amt,0) / nBRate, 2);
  NEW.BCst := Round(COALESCE(NEW.Amt,0) / nBRate, 2);
  Update Stor_SMat Set
         CQnt =COALESCE(CQnt ,0)+COALESCE(NEW.Qnt ,0),
         CAmt =COALESCE(CAmt ,0)+COALESCE(NEW.Cst ,0),
         CBAmt=COALESCE(CBAmt,0)+COALESCE(NEW.BCst,0)
   Where Stor_Id=nStr
     And Item_Id=NEW.Item_Id;
  NEW.LotSer   := COALESCE(NEW.LotSer  ,'-');
  NEW.Model_Id := COALESCE(NEW.Model_Id,0  );
  NEW.Color_Id := COALESCE(NEW.Color_Id,0  );
  NEW.Size_Id  := COALESCE(NEW.Size_Id ,0  );
  NEW.nLength  := COALESCE(NEW.nLength ,0  );
  NEW.nWidth   := COALESCE(NEW.nWidth  ,0  );
  NEW.nHeight  := COALESCE(NEW.nHeight ,0  );
  nIcsId := get_ICS_Id(NEW.Item_Id, NEW.LotSer, NEW.Unit_Id, NEW.Model_Id, NEW.Size_Id, NEW.Color_Id, NEW.nLength, NEW.nWidth, NEW.nHeight);
  NEW.Ics_Id := nIcsId;
  If COALESCE(nIcsId,0)>0 Then
    Begin
      UPDATE Stor_ICS SET
             CQnt =COALESCE(CQnt ,0)+COALESCE(NEW.Qnt ,0),
             CWQnt=COALESCE(CWQnt,0)+COALESCE(NEW.WQnt,0),
             CCst =COALESCE(CCst ,0)+COALESCE(NEW.Cst ,0),
             CBCst=COALESCE(CBCst,0)+COALESCE(NEW.BCst,0)
       WHERE Id=NEW.Ics_Id;
    Exception
      When OTHERS Then
        NULL;
    End;
  Else
    SELECT  CPrice,  NPrice,  DPrice,  SPrice,  WPrice,  RPrice,  HPrice,  MPrice
      INTO nCPrice, nNPrice, nDPrice, nSPrice, nWPrice, nRPrice, nHPrice, nMPrice
      FROM Stor_Item
     WHERE Id=NEW.Item_Id;
    bPrices := false;
    SELECT nextval('Stor_ICS_Seq')
      INTO nIcsId;
    NEW.Ics_Id := nIcsId;
    INSERT INTO Stor_ICS
          ( Id      , Item_Id , Unit_Id , Model_Id, Color_Id, Size_Id , nLength , nWidth  ,
            nHeight , Qnt     , CCst    , CBCst   , CQnt    , WQnt    , CWQnt   , CPrice  ,
            NPrice  , DPrice  , SPrice  , WPrice  , RPrice  , HPrice  , MPrice  , Barcode ,
            LotSer  , SDate   , EDate
          )
    VALUES( nIcsId       , NEW.Item_Id , NEW.Unit_Id , NEW.Model_Id, NEW.Color_Id, NEW.Size_Id , NEW.nLength , NEW.nWidth  ,
            NEW.nHeight , NEW.Qnt     , NEW.Cst     , NEW.BCst    , NEW.Qnt     , NEW.WQnt    , NEW.WQnt    , nCPrice      ,
            nNPrice      , nDPrice      , nSPrice      , nWPrice      , nRPrice      , nHPrice      , nMPrice      , NEW.Barcode ,
            NEW.LotSer  , NEW.SDate   , NEW.EDate
          );
  End If;
  Begin
    SELECT Id
      INTO nSIcsId
      FROM Stor_SICS
     WHERE Stor_Id=nStr
       AND Item_Id=NEW.Item_Id
       AND ICS_Id =NEW.Ics_Id;
    NEW.SICS_Id := nSIcsId;
    Begin
      UPDATE Stor_SICS SET
             CQnt =COALESCE(CQnt ,0)+COALESCE(NEW.Qnt ,0),
             CWQnt=COALESCE(CWQnt,0)+COALESCE(NEW.WQnt,0),
             CCst =COALESCE(CCst ,0)+COALESCE(NEW.Cst ,0),
             CBCst=COALESCE(CBCst,0)+COALESCE(NEW.BCst,0)
       WHERE Id=NEW.SICS_Id;
    Exception
      When OTHERS Then
        NULL;
    End;
  Exception
    When No_Data_Found Then
      If bPrices Then
        SELECT  CPrice,  NPrice,  DPrice,  SPrice,  WPrice,  RPrice,  HPrice,  MPrice
          INTO nCPrice, nNPrice, nDPrice, nSPrice, nWPrice, nRPrice, nHPrice, nMPrice
          FROM Stor_Item
         WHERE Id=NEW.Item_Id;
      End If;
      SELECT nextval('Stor_SICS_Seq')
        INTO nSIcsId;
      NEW.SICS_Id := nSIcsId;
      Begin
        INSERT INTO Stor_SICS
              ( Id          , Stor_Id , Item_Id     , ICS_Id     ,
                Qnt         , CCst    , CBCst       , CQnt       , WQnt     , CWQnt    ,
                CPrice      , NPrice  , DPrice      , SPrice     , WPrice   , RPrice   , HPrice , MPrice
              )
        VALUES( NEW.SICS_Id, nStr    , NEW.Item_Id, NEW.ICS_Id,
                NEW.Qnt    , NEW.Cst, NEW.BCst   , NEW.Qnt   , NEW.WQnt, NEW.WQnt,
                nCPrice     , nNPrice , nDPrice     , nSPrice    , nWPrice  , nRPrice  , nHPrice, nMPrice
              );
      Exception
        When Others Then
          NULL;
      End;
  End;
Exception
  When No_Data_Found Then
    RAISE EXCEPTION '%', 'Undefined Item '||NEW.Item_Id||' In Store '||COALESCE(nStr,0)||' MstId='||NEW.Id;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

