CREATE OR REPLACE FUNCTION Stor_TBD_EOTrn_fn() RETURNS TRIGGER AS $$
Declare
  nStr    NUMERIC;
Begin
  Select Stor_Id
    Into nStr
    From Stor_EOMst
    Where Id=OLD.Mst_Id;
  Update Stor_SMat Set
         CQnt =COALESCE(CQnt ,0)+COALESCE(OLD.Qnt ,0),
         CAmt =COALESCE(CAmt ,0)+COALESCE(OLD.Cst ,0),
         CBAmt=COALESCE(CBAmt,0)+COALESCE(OLD.BCst,0)
   Where Stor_Id=nStr
     And Item_Id=OLD.Item_Id;
  If OLD.TOrd_Id IS NOT NULL Then
    Update Stor_OuOrdTrn Set
           CQnt=COALESCE(CQnt,0)-COALESCE(OLD.Qnt,0)
     Where Id=OLD.TOrd_Id;
  End If;
  Begin
    UPDATE Stor_ICS SET
           CQnt =COALESCE(CQnt ,0)+COALESCE(OLD.Qnt ,0),
           CWQnt=COALESCE(CWQnt,0)+COALESCE(OLD.WQnt,0),
           CCst =COALESCE(CCst ,0)+COALESCE(OLD.Cst ,0),
           CBCst=COALESCE(CBCst,0)+COALESCE(OLD.BCst,0)
     WHERE Id=OLD.Ics_Id;
  Exception
    When OTHERS Then
      NULL;
  End;
  Begin
    UPDATE Stor_SICS SET
           CQnt =COALESCE(CQnt ,0)+COALESCE(OLD.Qnt ,0),
           CWQnt=COALESCE(CWQnt,0)+COALESCE(OLD.WQnt,0),
           CCst =COALESCE(CCst ,0)+COALESCE(OLD.Cst ,0),
           CBCst=COALESCE(CBCst,0)+COALESCE(OLD.BCst,0)
     WHERE Id=OLD.SIcs_Id;
  Exception
    When OTHERS Then
      NULL;
  End;
Exception
  When No_Data_Found Then
    RAISE EXCEPTION '%', 'Undefined Item '||OLD.Item_Id||' In Store '||nStr;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

