-- REVIEW(port): trigger translated mechanically; verify before use.

CREATE OR REPLACE FUNCTION Stor_TBI_TrTrn_fn() RETURNS TRIGGER AS $$
Declare
  nFStr    NUMERIC;
  nTStr    NUMERIC;
  nCst     NUMERIC;
  nBCst    NUMERIC;
  nQnt     NUMERIC;
  nBRate   NUMERIC := 0;
Begin
  Select StorF_Id, StorT_Id, Decode(Sign(COALESCE(BCurn_Rate,1)), -1,1, 0,1, COALESCE(BCurn_Rate,1))
    Into nFStr   , nTStr   , nBRate
    From Stor_TrMst
    Where Id=NEW.Mst_Id;
  nQnt := 0;
  nCst := 0;
  Select COALESCE(CQnt,0), COALESCE(CAmt,0), COALESCE(CBAmt,0)
    Into nQnt, nCst, nBCst
    From Stor_SMat
   Where Stor_Id=nFStr
     And Item_Id=NEW.Item_Id;
  If nQnt>0 Then
    nCst  := nCst  / nQnt;
    nBCst := nBCst / nQnt;
  End If;
  NEW.BAmt := Round(COALESCE(NEW.Amt,0) / nBRate, 2);
  NEW.Cst  := nCst  * NEW.Qnt;
  NEW.BCst := nBCst * NEW.Qnt;
  Update Stor_SMat Set
         CQnt =COALESCE(CQnt ,0)-COALESCE(NEW.Qnt ,0),
         CAmt =COALESCE(CAmt ,0)-COALESCE(NEW.Cst ,0),
         CBAmt=COALESCE(CBAmt,0)-COALESCE(NEW.BCst,0)
   Where Stor_Id=nFStr
     And Item_Id=NEW.Item_Id;
  Update Stor_SMat Set
         CQnt =COALESCE(CQnt ,0)+COALESCE(NEW.Qnt ,0),
         CAmt =COALESCE(CAmt ,0)+COALESCE(NEW.Cst ,0),
         CBAmt=COALESCE(CBAmt,0)+COALESCE(NEW.BCst,0)
   Where Stor_Id=nTStr
     And Item_Id=NEW.Item_Id;
  Begin
    UPDATE Stor_SICS SET
           CQnt =COALESCE(CQnt ,0)-COALESCE(NEW.Qnt ,0),
           CWQnt=COALESCE(CWQnt,0)-COALESCE(NEW.WQnt,0),
           CCst =COALESCE(CCst ,0)-COALESCE(NEW.Cst ,0),
           CBCst=COALESCE(CBCst,0)-COALESCE(NEW.BCst,0)
     WHERE Id=NEW.SIcs_FId;
  Exception
    When OTHERS Then
      NULL;
  End;
  Begin
    UPDATE Stor_SICS SET
           CQnt =COALESCE(CQnt ,0)+COALESCE(NEW.Qnt ,0),
           CWQnt=COALESCE(CWQnt,0)+COALESCE(NEW.WQnt,0),
           CCst =COALESCE(CCst ,0)+COALESCE(NEW.Cst ,0),
           CBCst=COALESCE(CBCst,0)+COALESCE(NEW.BCst,0)
     WHERE Id=NEW.SIcs_TId;
  Exception
    When OTHERS Then
      NULL;
  End;
Exception
  When No_Data_Found Then
    RAISE EXCEPTION '%', 'Undefined Item '||NEW.Item_Id||' In Store '||nFStr||', Store '||nTStr;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

